app.post("/api/house/:username/ping",async(req,res)=>{try{const me=await userFromReq(req);if(!me)return res.status(401).json({error:"Niet ingelogd"});const q=await pool.query("SELECT id,username FROM users WHERE username_lower=$1",[String(req.params.username||"").toLowerCase()]);const owner=q.rows[0];if(!owner)return res.status(404).json({error:"Woning niet gevonden."});await pool.query("INSERT INTO houses(user_id) VALUES($1) ON CONFLICT(user_id) DO NOTHING",[owner.id]);const h=(await pool.query("SELECT privacy FROM houses WHERE user_id=$1",[owner.id])).rows[0];const privacy=h.privacy||"public";if(owner.id!==me.id&&privacy!=="public")return res.status(403).json({error:"Deze woning is privé."});const room=houseRoom(owner.id);room.set(me.id,{username:me.username,seen:Date.now()});cleanHouseVisitors();const visitors=[...room.entries()].map(([id,v])=>({id,username:v.username}));const messages=(houseChats.get(owner.id)||[]).slice(-30);res.json({owner:owner.username,ownerId:owner.id,visitors,messages,isOwner:owner.id===me.id,privacy})}catch(e){res.status(500).json({error:"Huisstatus laden mislukt."})}});
app.post("/api/house/:username/chat",async(req,res)=>{try{const me=await userFromReq(req);if(!me)return res.status(401).json({error:"Niet ingelogd"});const q=await pool.query("SELECT id FROM users WHERE username_lower=$1",[String(req.params.username||"").toLowerCase()]);const owner=q.rows[0];if(!owner)return res.status(404).json({error:"Woning niet gevonden."});const room=houseRoom(owner.id);if(!room.has(me.id)&&owner.id!==me.id)return res.status(403).json({error:"Je bent niet in deze woning."});const message=String(req.body&&req.body.message||"").trim().slice(0,160);if(!message)return res.status(400).json({error:"Typ eerst een bericht."});const list=houseChats.get(owner.id)||[];list.push({id:Date.now(),username:me.username,message,at:new Date().toISOString()});houseChats.set(owner.id,list.slice(-50));res.json({ok:true})}catch(e){res.status(500).json({error:"Bericht sturen mislukt."})}});
app.post("/api/house/:username/kick",async(req,res)=>{try{const me=await userFromReq(req);if(!me)return res.status(401).json({error:"Niet ingelogd"});const q=await pool.query("SELECT id FROM users WHERE username_lower=$1",[String(req.params.username||"").toLowerCase()]);const owner=q.rows[0];if(!owner||owner.id!==me.id)return res.status(403).json({error:"Alleen de eigenaar kan bezoekers buitenzetten."});const target=String(req.body&&req.body.username||"").toLowerCase();const room=houseRoom(owner.id);for(const [id,v] of room)if(String(v.username).toLowerCase()===target&&id!==me.id)room.delete(id);res.json({ok:true})}catch(e){res.status(500).json({error:"Bezoeker verwijderen mislukt."})}});
app.post("/api/house/upgrade",async(req,res)=>{try{const me=await userFromReq(req);if(!me)return res.status(401).json({error:"Niet ingelogd"});await pool.query("INSERT INTO houses(user_id) VALUES($1) ON CONFLICT(user_id) DO NOTHING",[me.id]);const h=(await pool.query("SELECT house_level FROM houses WHERE user_id=$1",[me.id])).rows[0],level=Number(h.house_level||1);if(level>=5)return res.status(400).json({error:"Je huis is al maximaal level 5."});const costs=[0,25000,75000,175000,400000],cost=costs[level];const client=await pool.connect();try{await client.query("BEGIN");const pay=await client.query("UPDATE users SET money=money-$1 WHERE id=$2 AND money>=$1 RETURNING money",[cost,me.id]);if(!pay.rowCount){await client.query("ROLLBACK");return res.status(400).json({error:"Niet genoeg cash. Upgrade kost €"+cost.toLocaleString("nl-BE")+"."})}await client.query("UPDATE houses SET house_level=house_level+1,updated_at=NOW() WHERE user_id=$1",[me.id]);await client.query("COMMIT");res.json({ok:true,level:level+1,cost,money:pay.rows[0].money})}catch(e){try{await client.query("ROLLBACK")}catch{}throw e}finally{client.release()}}catch(e){console.error(e);res.status(500).json({error:e.message||"Huisupgrade mislukt."})}});
app.post("/api/house/style",async(req,res)=>{try{const me=await userFromReq(req);if(!me)return res.status(401).json({error:"Niet ingelogd"});const style=String(req.body&&req.body.style||"");if(!["basic","modern","luxury"].includes(style))return res.status(400).json({error:"Onbekende huisstijl."});await pool.query("INSERT INTO houses(user_id,style) VALUES($1,$2) ON CONFLICT(user_id) DO UPDATE SET style=EXCLUDED.style,updated_at=NOW()",[me.id,style]);res.json({ok:true,style})}catch(e){res.status(500).json({error:"Huisstijl opslaan mislukt."})}});
app.get("/api/properties",async(req,res)=>{try{const u=await userFromReq(req);if(!u)return res.status(401).json({error:"Niet ingelogd"});const q=await pool.query("SELECT id,property_key,name,value,prestige,property_level,income,last_income_at,bought_at FROM user_properties WHERE user_id=$1 ORDER BY value",[u.id]);res.json({properties:q.rows})}catch(e){console.error(e);res.status(500).json({error:"Vastgoed laden mislukt."})}});app.post("/api/property/buy",async(req,res)=>{const items={flat:{name:"Appartement",price:15000,prestige:5},house:{name:"Stadswoning",price:50000,prestige:15},villa:{name:"Luxe Villa",price:150000,prestige:40},penthouse:{name:"Penthouse",price:350000,prestige:80}};const item=items[String(req.body&&req.body.property||"")];if(!item)return res.status(400).json({error:"Onbekend vastgoed."});const client=await pool.connect();try{const u=await userFromReq(req);if(!u)return res.status(401).json({error:"Niet ingelogd"});await client.query("BEGIN");const own=await client.query("SELECT 1 FROM user_properties WHERE user_id=$1 AND property_key=$2",[u.id,String(req.body.property)]);if(own.rows[0]){await client.query("ROLLBACK");return res.status(400).json({error:"Je bezit dit vastgoed al."})}const q=await client.query("UPDATE users SET money=money-$1 WHERE id=$2 AND money>=$1 RETURNING username,money,bank,energy,xp,level,car,equipment,jailed_until,hospital_until,hp,is_admin,energy_updated_at",[item.price,u.id]);if(!q.rows[0]){await client.query("ROLLBACK");return res.status(400).json({error:"Niet genoeg cash."})}await client.query("INSERT INTO user_properties(user_id,property_key,name,value,prestige) VALUES($1,$2,$3,$4,$5)",[u.id,String(req.body.property),item.name,item.price,item.prestige]);await client.query("COMMIT");res.json({ok:true,property:item.name,user:publicUser(q.rows[0])})}catch(e){try{await client.query("ROLLBACK")}catch{}console.error(e);res.status(500).json({error:"Aankoop mislukt."})}finally{client.release()}});app.post("/api/property/upgrade",async(req,res)=>{try{const u=await userFromReq(req);if(!u)return res.status(401).json({error:"Niet ingelogd"});const key=String(req.body.property||"");const p=await pool.query("SELECT * FROM user_properties WHERE user_id=$1 AND property_key=$2",[u.id,key]);if(!p.rows[0])return res.status(404).json({error:"Vastgoed niet gevonden."});const level=Number(p.rows[0].property_level||1);if(level>=5)return res.status(400).json({error:"Maximaal level bereikt."});const cost=Math.round(Number(p.rows[0].value)*(.25*level));const c=await pool.connect();try{await c.query("BEGIN");const pay=await c.query("UPDATE users SET money=money-$1 WHERE id=$2 AND money>=$1",[cost,u.id]);if(!pay.rowCount){await c.query("ROLLBACK");return res.status(400).json({error:"Niet genoeg cash."})}await c.query("UPDATE user_properties SET property_level=property_level+1,income=GREATEST(income,$1) WHERE id=$2",[Math.round(Number(p.rows[0].value)*.01*(level+1)),p.rows[0].id]);await c.query("COMMIT")}finally{c.release()}const nu=await userFromReq(req);res.json({user:publicUser(nu),cost})}catch(e){console.error(e);res.status(500).json({error:"Upgrade mislukt."})}});app.post("/api/property/income",async(req,res)=>{try{const u=await userFromReq(req);if(!u)return res.status(401).json({error:"Niet ingelogd"});const q=await pool.query("SELECT COALESCE(SUM(GREATEST(income,ROUND(value*.01*property_level))),0)::int total,MIN(last_income_at) last FROM user_properties WHERE user_id=$1",[u.id]);const total=Number(q.rows[0].total||0);if(!total)return res.status(400).json({error:"Je hebt nog geen vastgoed."});if(q.rows[0].last&&Date.now()-new Date(q.rows[0].last).getTime()<86400000)return res.status(400).json({error:"Je vastgoedinkomsten zijn nog niet klaar. Kom later terug."});await pool.query("UPDATE users SET money=money+$1 WHERE id=$2",[total,u.id]);await pool.query("UPDATE user_properties SET last_income_at=NOW() WHERE user_id=$1",[u.id]);const nu=await userFromReq(req);res.json({user:publicUser(nu),amount:total})}catch(e){console.error(e);res.status(500).json({error:"Inkomsten ophalen mislukt."})}});app.get("/api/news",async(req,res)=>{try{const u=await userFromReq(req);if(!u)return res.status(401).json({error:"Niet ingelogd"});const q=await pool.query("SELECT id,message,created_at FROM news_ticker ORDER BY created_at DESC LIMIT 20");res.json({news:q.rows,isAdmin:!!u.is_admin})}catch(e){console.error(e);res.status(500).json({error:"Nieuws laden mislukt."})}});
app.post("/api/news",async(req,res)=>{try{const u=await userFromReq(req);if(!u)return res.status(401).json({error:"Niet ingelogd"});if(!u.is_admin)return res.status(403).json({error:"Alleen admins kunnen nieuws plaatsen."});const message=String(req.body&&req.body.message||"").trim().slice(0,240);if(!message)return res.status(400).json({error:"Vul een nieuwsbericht in."});await pool.query("INSERT INTO news_ticker(message,created_by) VALUES($1,$2)",[message,u.id]);res.json({ok:true})}catch(e){console.error(e);res.status(500).json({error:"Nieuws plaatsen mislukt."})}});
app.delete("/api/news/:id",async(req,res)=>{try{const u=await userFromReq(req);if(!u)return res.status(401).json({error:"Niet ingelogd"});if(!u.is_admin)return res.status(403).json({error:"Alleen admins kunnen nieuws verwijderen."});await pool.query("DELETE FROM news_ticker WHERE id=$1",[Number(req.params.id)||0]);res.json({ok:true})}catch(e){console.error(e);res.status(500).json({error:"Nieuws verwijderen mislukt."})}});
app.get("/api/garage",async(req,res)=>{try{const u=await userFromReq(req);if(!u)return res.status(401).json({error:"Niet ingelogd"});const q=await pool.query("SELECT id,car_key,name,value,condition,source,acquired_at FROM user_cars WHERE user_id=$1 ORDER BY acquired_at DESC,id DESC",[u.id]);res.json({cars:q.rows})}catch(e){console.error(e);res.status(500).json({error:"Garage kon niet worden geladen."})}});app.post("/api/car",async(req,res)=>{try{const u=await userFromReq(req);if(!u)return res.status(401).json({error:"Niet ingelogd"});const cars={golf:{name:"Volkswagen Golf GTI",price:75000},bmw:{name:"BMW M3",price:250000},lambo:{name:"Lamborghini Huracan",price:500000}};const car=cars[String(req.body.car||"")];if(!car)return res.status(400).json({error:"Onbekende auto."});const client=await pool.connect();try{await client.query("BEGIN");const q=await client.query("UPDATE users SET money=money-$1,car=$2 WHERE id=$3 AND money>=$1 RETURNING username,money,bank,energy,xp,level,car,equipment",[car.price,car.name,u.id]);if(!q.rows[0]){await client.query("ROLLBACK");return res.status(400).json({error:"Niet genoeg cash voor deze auto."})}await client.query("INSERT INTO user_cars(user_id,car_key,name,value,condition,source) VALUES($1,$2,$3,$4,100,'bought')",[u.id,String(req.body.car||""),car.name,car.price]);await client.query("COMMIT");res.json({user:publicUser(q.rows[0]),car:car.name,price:car.price})}catch(e){await client.query("ROLLBACK");throw e}finally{client.release()}}catch(e){console.error(e);res.status(500).json({error:"Aankoop mislukt."})}});app.post("/api/weapon",async(req,res)=>{try{const u=await userFromReq(req);if(!u)return res.status(401).json({error:"Niet ingelogd"});const weapons={pistol:{name:"Pistool",price:2000,damage:10},shotgun:{name:"Shotgun",price:5000,damage:20},smg:{name:"SMG",price:9000,damage:30}};const w=weapons[String(req.body.weapon||"")];if(!w)return res.status(400).json({error:"Onbekend wapen."});const q=await pool.query("UPDATE users SET money=money-$1,weapon=$2 WHERE id=$3 AND money>=$1 RETURNING username,money,bank,energy,xp,level,car,equipment,hp,weapon", [w.price,w.name,u.id]);if(!q.rows[0])return res.status(400).json({error:"Niet genoeg cash."});await pool.query("INSERT INTO inventory_items(user_id,item_type,item_key,name,quantity) VALUES($1,'weapon',$2,$3,1)",[u.id,String(req.body.weapon||""),w.name]);res.json({user:publicUser(q.rows[0]),weapon:w.name,damage:w.damage,price:w.price})}catch(e){console.error(e);res.status(500).json({error:"Wapen kopen mislukt."})}});app.post("/api/equipment",async(req,res)=>{try{const u=await userFromReq(req);if(!u)return res.status(401).json({error:"Niet ingelogd"});const items={vest:{name:"Beschermvest",price:1500},radio:{name:"Versleutelde radio",price:2500},tools:{name:"Inbrekersgereedschap",price:4000}};const item=items[String(req.body.item||"")];if(!item)return res.status(400).json({error:"Onbekend item."});const q=await pool.query("UPDATE users SET money=money-$1,equipment=$2 WHERE id=$3 AND money>=$1 RETURNING username,money,bank,energy,xp,level,car,equipment",[item.price,item.name,u.id]);if(!q.rows[0])return res.status(400).json({error:"Niet genoeg cash."});await pool.query("INSERT INTO inventory_items(user_id,item_type,item_key,name,quantity) VALUES($1,'equipment',$2,$3,1)",[u.id,String(req.body.item||""),item.name]);res.json({user:publicUser(q.rows[0]),item:item.name,price:item.price})}catch(e){console.error(e);res.status(500).json({error:"Aankoop mislukt."})}});app.post("/api/daily",async(req,res)=>{try{const u=await userFromReq(req);if(!u)return res.status(401).json({error:"Niet ingelogd"});const q=await pool.query("UPDATE users SET money=money+1000,daily_claimed_at=NOW() WHERE id=$1 AND (daily_claimed_at IS NULL OR daily_claimed_at<=NOW()-INTERVAL '24 hours') RETURNING username,money,bank,energy,xp,level,car,equipment",[u.id]);if(!q.rows[0])return res.status(400).json({error:"Je dagelijkse beloning is nog niet beschikbaar. Probeer later opnieuw."});res.json({user:publicUser(q.rows[0]),reward:1000})}catch(e){console.error(e);res.status(500).json({error:"Dagelijkse beloning mislukt."})}});app.get("/api/leaderboard",async(req,res)=>{try{const u=await userFromReq(req);if(!u)return res.status(401).json({error:"Niet ingelogd"});const q=await pool.query("SELECT u.username,u.level,u.xp,u.money,u.bank,u.avatar,u.crimes_done,(SELECT COUNT(*)::int FROM user_cars uc WHERE uc.user_id=u.id) AS car_count FROM users u ORDER BY u.level DESC,u.xp DESC LIMIT 100");res.json({players:q.rows})}catch(e){console.error(e);res.status(500).json({error:"Ranglijst kon niet worden geladen."})}});app.get("/api/players",async(req,res)=>{try{const u=await userFromReq(req);if(!u)return res.status(401).json({error:"Niet ingelogd"});const privileged=!!(u.is_admin||u.is_mod);const q=await pool.query(privileged?"SELECT u.username,u.level,u.xp,u.money,u.bank,u.energy,u.hp,u.jailed_until,EXISTS(SELECT 1 FROM sessions s WHERE s.user_id=u.id AND s.expires_at>NOW() AND s.last_seen>NOW()-INTERVAL '2 minutes') AS online FROM users u ORDER BY online DESC,u.level DESC,u.xp DESC,u.created_at ASC LIMIT 100":"SELECT u.username,u.level,u.xp,EXISTS(SELECT 1 FROM sessions s WHERE s.user_id=u.id AND s.expires_at>NOW() AND s.last_seen>NOW()-INTERVAL '2 minutes') AS online FROM users u ORDER BY online DESC,u.level DESC,u.xp DESC,u.created_at ASC LIMIT 100");res.json({players:q.rows,privileged})}catch(e){console.error(e);res.status(500).json({error:"Spelers konden niet worden geladen."})}});app.get("/api/player/:username",async(req,res)=>{try{const me=await userFromReq(req);if(!me)return res.status(401).json({error:"Niet ingelogd"});const q=await pool.query("SELECT u.username,u.level,u.xp,u.money,u.bank,u.car,u.equipment,u.avatar,u.crimes_done,u.hp,u.weapon,u.created_at,f.name AS family,(SELECT COUNT(*)::int FROM user_cars uc WHERE uc.user_id=u.id) AS car_count,(SELECT COUNT(*)::int FROM attacks a WHERE a.attacker_id=u.id) AS attacks FROM users u LEFT JOIN family_members fm ON fm.user_id=u.id LEFT JOIN families f ON f.id=fm.family_id WHERE u.username_lower=$1",[String(req.params.username||"").toLowerCase()]);if(!q.rows[0])return res.status(404).json({error:"Speler niet gevonden."});res.json({player:q.rows[0]})}catch(e){console.error(e);res.status(500).json({error:"Profiel kon niet worden geladen."})}});app.post("/api/profile/avatar",async(req,res)=>{try{const u=await userFromReq(req);if(!u)return res.status(401).json({error:"Niet ingelogd"});const allowed=["🕴️","😎","🥷","🕵️","👑","💀","🤵","🧔"];const avatar=String(req.body.avatar||"");if(!allowed.includes(avatar))return res.status(400).json({error:"Ongeldige avatar."});await pool.query("UPDATE users SET avatar=$1 WHERE id=$2",[avatar,u.id]);res.json({ok:true,avatar})}catch(e){console.error(e);res.status(500).json({error:"Avatar kon niet worden opgeslagen."})}});app.post("/api/attack",async(req,res)=>{const client=await pool.connect();try{const u=await userFromReq(req);if(!u)return res.status(401).json({error:"Niet ingelogd"});if(u.energy<2)return res.status(400).json({error:"Je hebt minstens 2 energie nodig."});const name=String(req.body.username||"").toLowerCase();await client.query("BEGIN");const tq=await client.query("SELECT id,username,money,hp,weapon,equipment,hospital_until FROM users WHERE username_lower=$1 FOR UPDATE",[name]);const t=tq.rows[0];if(!t){await client.query("ROLLBACK");return res.status(404).json({error:"Speler niet gevonden."})}if(t.id===u.id){await client.query("ROLLBACK");return res.status(400).json({error:"Je kunt jezelf niet aanvallen."})}if(t.hospital_until&&new Date(t.hospital_until)>new Date()){await client.query("ROLLBACK");return res.status(400).json({error:"Deze speler ligt al in het ziekenhuis."})}const last=await client.query("SELECT attacked_at FROM attacks WHERE attacker_id=$1 AND target_id=$2",[u.id,t.id]);if(last.rows[0]&&Date.now()-new Date(last.rows[0].attacked_at).getTime()<3600000){await client.query("ROLLBACK");return res.status(400).json({error:"Je moet 1 uur wachten voor je deze speler opnieuw kunt aanvallen."})}const dmg={Pistool:10,Shotgun:20,SMG:30};const weaponDamage=dmg[u.weapon]||5;const defense=t.equipment==="Beschermvest"?10:0;const chance=Math.max(30,Math.min(75,50+weaponDamage-defense));const success=crypto.randomInt(100)<chance;const damage=success?Math.max(5,crypto.randomInt(Math.max(6,weaponDamage),Math.max(7,weaponDamage+16))-defense):0;const newHp=Math.max(0,Number(t.hp??100)-damage);const hospitalized=success&&newHp<=0;const stolen=success?Math.min(t.money,crypto.randomInt(250,1001)):0;let xp=u.xp+(success?40:8),level=u.level;if(xp>=100){level+=Math.floor(xp/100);xp%=100}if(success)await client.query("UPDATE users SET money=money-$1,hp=$2,hospital_until=CASE WHEN $3 THEN NOW()+INTERVAL '10 minutes' ELSE hospital_until END WHERE id=$4",[stolen,newHp,hospitalized,t.id]);const aq=await client.query("UPDATE users SET money=money+$1,energy=energy-2,xp=$2,level=$3,energy_updated_at=CASE WHEN energy=100 THEN NOW() ELSE energy_updated_at END WHERE id=$4 AND energy>=2 RETURNING username,money,bank,energy,xp,level,car,equipment,hp,hospital_until,is_admin",[stolen,xp,level,u.id]);if(!aq.rows[0]){await client.query("ROLLBACK");return res.status(400).json({error:"Je hebt niet genoeg energie."})}await client.query("INSERT INTO attacks(attacker_id,target_id,attacked_at) VALUES($1,$2,NOW()) ON CONFLICT(attacker_id,target_id) DO UPDATE SET attacked_at=NOW()",[u.id,t.id]);const msg=success?("⚔️ "+u.username+" viel je aan: -"+damage+" HP en €"+stolen+" gestolen!"+(hospitalized?" 🏥 Je ligt 10 minuten in het ziekenhuis.":"")):("🛡️ Je hebt de aanval van "+u.username+" afgeslagen!");await client.query("INSERT INTO notifications(user_id,message) VALUES($1,$2)",[t.id,msg]);await client.query("COMMIT");res.json({user:publicUser(aq.rows[0]),success,stolen,damage,target:t.username,targetHp:newHp,hospitalized,chance,weapon:u.weapon||"Vuisten"})}catch(e){await client.query("ROLLBACK");console.error(e);res.status(500).json({error:"Aanval mislukt."})}finally{client.release()}});app.get("/api/family",async(req,res)=>{try{const u=await userFromReq(req);if(!u)return res.status(401).json({error:"Niet ingelogd"});const mine=await pool.query("SELECT f.id,f.name,f.owner_id FROM family_members m JOIN families f ON f.id=m.family_id WHERE m.user_id=$1",[u.id]);if(mine.rows[0]){const members=await pool.query("SELECT u.username,u.level FROM family_members m JOIN users u ON u.id=m.user_id WHERE m.family_id=$1 ORDER BY u.level DESC,u.username",[mine.rows[0].id]);return res.json({family:{name:mine.rows[0].name,owner:mine.rows[0].owner_id===u.id,members:members.rows}})}const all=await pool.query("SELECT f.id,f.name,COUNT(m.user_id)::int AS members FROM families f LEFT JOIN family_members m ON m.family_id=f.id GROUP BY f.id ORDER BY f.name LIMIT 50");res.json({family:null,families:all.rows})}catch(e){console.error(e);res.status(500).json({error:"Families konden niet worden geladen."})}});app.post("/api/family/create",async(req,res)=>{try{const u=await userFromReq(req);if(!u)return res.status(401).json({error:"Niet ingelogd"});const name=String(req.body.name||"").trim();if(!/^[A-Za-z0-9 _-]{3,24}$/.test(name))return res.status(400).json({error:"Familienaam: 3-24 tekens."});const client=await pool.connect();try{await client.query("BEGIN");const exists=await client.query("SELECT 1 FROM family_members WHERE user_id=$1",[u.id]);if(exists.rows[0]){await client.query("ROLLBACK");return res.status(400).json({error:"Je zit al in een familie."})}const q=await client.query("INSERT INTO families(name,owner_id) VALUES($1,$2) RETURNING id",[name,u.id]);await client.query("INSERT INTO family_members(user_id,family_id) VALUES($1,$2)",[u.id,q.rows[0].id]);await client.query("COMMIT");res.json({ok:true})}catch(e){await client.query("ROLLBACK");if(e.code==="23505")return res.status(409).json({error:"Deze familienaam bestaat al."});throw e}finally{client.release()}}catch(e){console.error(e);res.status(500).json({error:"Familie maken mislukt."})}});app.post("/api/family/join",async(req,res)=>{try{const u=await userFromReq(req);if(!u)return res.status(401).json({error:"Niet ingelogd"});const familyId=Number(req.body.familyId);if(!Number.isSafeInteger(familyId)||familyId<=0)return res.status(400).json({error:"Ongeldige familie."});await pool.query("INSERT INTO family_members(user_id,family_id) VALUES($1,$2)",[u.id,familyId]);res.json({ok:true})}catch(e){if(e.code==="23505")return res.status(400).json({error:"Je zit al in een familie."});if(e.code==="23503")return res.status(404).json({error:"Familie bestaat niet."});console.error(e);res.status(500).json({error:"Aansluiten mislukt."})}});app.post("/api/admin/energy",async(req,res)=>{try{const u=await userFromReq(req);if(!u)return res.status(401).json({error:"Niet ingelogd"});if(!u.is_admin)return res.status(403).json({error:"Geen adminrechten."});const q=await pool.query("UPDATE users SET energy=10,energy_updated_at=NOW() WHERE id=$1 RETURNING username,money,bank,energy,xp,level,car,equipment,jailed_until,is_admin",[u.id]);res.json({user:publicUser(q.rows[0])})}catch(e){console.error(e);res.status(500).json({error:"Adminactie mislukt."})}});app.post("/api/mod/player-energy",async(req,res)=>{try{const u=await userFromReq(req);if(!u)return res.status(401).json({error:"Niet ingelogd"});if(!u.is_mod&&!u.is_admin)return res.status(403).json({error:"Geen moderatorrechten."});const username=String(req.body.username||"").trim(),amount=Math.max(1,Math.min(100,Number(req.body.amount)||0));if(!username||!Number(req.body.amount))return res.status(400).json({error:"Kies een speler en hoeveelheid energie."});const q=await pool.query("UPDATE users SET energy=LEAST(100,energy+$1),energy_updated_at=NOW() WHERE username_lower=$2 RETURNING username,energy",[amount,username.toLowerCase()]);if(!q.rows[0])return res.status(404).json({error:"Speler niet gevonden."});res.json({ok:true,username:q.rows[0].username,energy:q.rows[0].energy})}catch(e){res.status(500).json({error:"Moderatoractie mislukt."})}});app.post("/api/mod/release",async(req,res)=>{try{const u=await userFromReq(req);if(!u)return res.status(401).json({error:"Niet ingelogd"});if(!u.is_mod&&!u.is_admin)return res.status(403).json({error:"Geen moderatorrechten."});const username=String(req.body.username||"").trim();if(!username)return res.status(400).json({error:"Kies een speler."});const q=await pool.query("UPDATE users SET jailed_until=NULL WHERE username_lower=$1 RETURNING username",[username.toLowerCase()]);if(!q.rows[0])return res.status(404).json({error:"Speler niet gevonden."});res.json({ok:true,username:q.rows[0].username})}catch(e){res.status(500).json({error:"Moderatoractie mislukt."})}});app.post("/api/admin/money",async(req,res)=>{try{const u=await userFromReq(req);if(!u)return res.status(401).json({error:"Niet ingelogd"});if(!u.is_admin)return res.status(403).json({error:"Geen adminrechten."});const username=String(req.body.username||"").trim();const amount=Number(req.body.amount);if(!username||!Number.isSafeInteger(amount)||amount<1||amount>1000000)return res.status(400).json({error:"Kies een speler en een bedrag van €1 tot €1.000.000."});const q=await pool.query("UPDATE users SET money=money+$1 WHERE username_lower=$2 RETURNING username,money", [amount,username.toLowerCase()]);if(!q.rows[0])return res.status(404).json({error:"Speler niet gevonden."});res.json({ok:true,username:q.rows[0].username,amount,money:q.rows[0].money})}catch(e){console.error(e);res.status(500).json({error:"Geld geven mislukt."})}});app.post("/api/admin/player-energy",async(req,res)=>{try{const u=await userFromReq(req);if(!u)return res.status(401).json({error:"Niet ingelogd"});if(!u.is_admin)return res.status(403).json({error:"Geen adminrechten."});const username=String(req.body.username||"").trim(),amount=Math.max(1,Math.min(100,Number(req.body.amount)||0));if(!username)return res.status(400).json({error:"Kies een speler."});if(!Number(req.body.amount)||Number(req.body.amount)<1)return res.status(400).json({error:"Vul een hoeveelheid energie in."});const q=await pool.query("UPDATE users SET energy=LEAST(100,energy+$1),energy_updated_at=NOW() WHERE username_lower=$2 RETURNING username,energy",[amount,username.toLowerCase()]);if(!q.rows[0])return res.status(404).json({error:"Speler niet gevonden."});res.json({ok:true,username:q.rows[0].username,energy:q.rows[0].energy})}catch(e){console.error(e);res.status(500).json({error:"Energie geven mislukt."})}});app.post("/api/admin/release",async(req,res)=>{try{const u=await userFromReq(req);if(!u)return res.status(401).json({error:"Niet ingelogd"});if(!u.is_admin)return res.status(403).json({error:"Geen adminrechten."});const username=String(req.body.username||"").trim();if(!username)return res.status(400).json({error:"Kies een speler."});const q=await pool.query("UPDATE users SET jailed_until=NULL WHERE username_lower=$1 RETURNING username",[username.toLowerCase()]);if(!q.rows[0])return res.status(404).json({error:"Speler niet gevonden."});res.json({ok:true,username:q.rows[0].username})}catch(e){console.error(e);res.status(500).json({error:"Vrijlaten mislukt."})}});app.delete("/api/admin/player",async(req,res)=>{try{const admin=await userFromReq(req);if(!admin)return res.status(401).json({error:"Niet ingelogd"});if(!admin.is_admin)return res.status(403).json({error:"Geen adminrechten."});const username=String(req.body.username||"").trim().toLowerCase();if(!username)return res.status(400).json({error:"Kies een speler."});const target=await pool.query("SELECT id,username,is_admin FROM users WHERE username_lower=$1",[username]);if(!target.rows[0])return res.status(404).json({error:"Speler niet gevonden."});if(Number(target.rows[0].id)===Number(admin.id))return res.status(400).json({error:"Je kunt je eigen adminaccount niet verwijderen."});if(target.rows[0].is_admin)return res.status(400).json({error:"Een ander adminaccount kan hier niet worden verwijderd."});const q=await pool.query("DELETE FROM users WHERE id=$1 RETURNING username",[target.rows[0].id]);res.json({ok:true,username:q.rows[0].username})}catch(e){console.error(e);res.status(500).json({error:"Account verwijderen mislukt."})}});app.post("/api/hospital/heal",async(req,res)=>{try{const u=await userFromReq(req);if(!u)return res.status(401).json({error:"Niet ingelogd"});const cost=5000;if(u.money<cost)return res.status(400).json({error:"Je hebt €5.000 nodig voor een spoedbehandeling."});const q=await pool.query("UPDATE users SET money=money-$1,hp=100,hospital_until=NULL WHERE id=$2 RETURNING username,money,bank,energy,xp,level,car,equipment,energy_updated_at,jailed_until,hospital_until,hp,is_admin",[cost,u.id]);res.json({user:publicUser(q.rows[0]),cost})}catch(e){console.error(e);res.status(500).json({error:"Behandeling mislukt."})}});app.post("/api/inventory/use",async(req,res)=>{try{const u=await userFromReq(req);if(!u)return res.status(401).json({error:"Niet ingelogd"});const key=String(req.body.item||"");const items={medkit:{name:"Medkit"},energy:{name:"Energy Drink"},firstaid:{name:"EHBO-koffer"},boost:{name:"Energy Booster"}};const item=items[key];if(!item)return res.status(400).json({error:"Dit item kan je niet gebruiken."});const client=await pool.connect();try{await client.query("BEGIN");const iq=await client.query("SELECT id,quantity FROM inventory_items WHERE user_id=$1 AND item_key=$2 AND quantity>0 ORDER BY acquired_at LIMIT 1 FOR UPDATE",[u.id,key]);if(!iq.rows[0]){await client.query("ROLLBACK");return res.status(400).json({error:"Je hebt dit item niet."})}if(key==="medkit")await client.query("UPDATE users SET hp=LEAST(100,hp+50) WHERE id=$1",[u.id]);if(key==="energy")await client.query("UPDATE users SET energy=LEAST(100,energy+25) WHERE id=$1",[u.id]);if(key==="firstaid")await client.query("UPDATE users SET hp=100 WHERE id=$1",[u.id]);if(key==="boost")await client.query("UPDATE users SET energy=100 WHERE id=$1",[u.id]);await client.query("UPDATE inventory_items SET quantity=quantity-1 WHERE id=$1",[iq.rows[0].id]);await client.query("DELETE FROM inventory_items WHERE id=$1 AND quantity<=0",[iq.rows[0].id]);await client.query("COMMIT");const q=await pool.query("SELECT id,username,money,bank,energy,xp,level,car,equipment,energy_updated_at,jailed_until,hospital_until,hp,is_admin FROM users WHERE id=$1",[u.id]);res.json({user:publicUser(q.rows[0]),used:item.name})}catch(e){await client.query("ROLLBACK");throw e}finally{client.release()}}catch(e){console.error(e);res.status(500).json({error:"Item gebruiken mislukt."})}});app.post("/api/inventory/buy",async(req,res)=>{try{const u=await userFromReq(req);if(!u)return res.status(401).json({error:"Niet ingelogd"});const items={medkit:{name:"Medkit",price:2500},energy:{name:"Energy Drink",price:1000},firstaid:{name:"EHBO-koffer",price:6000},boost:{name:"Energy Booster",price:3500}};const key=String(req.body.item||"");const item=items[key];if(!item)return res.status(400).json({error:"Onbekend item."});const q=await pool.query("UPDATE users SET money=money-$1 WHERE id=$2 AND money>=$1 RETURNING money",[item.price,u.id]);if(!q.rows[0])return res.status(400).json({error:"Niet genoeg cash."});await pool.query("INSERT INTO inventory_items(user_id,item_type,item_key,name,quantity) VALUES($1,'consumable',$2,$3,1)",[u.id,key,item.name]);res.json({ok:true,item:item.name,price:item.price,money:q.rows[0].money})}catch(e){console.error(e);res.status(500).json({error:"Aankoop mislukt."})}});app.get("/api/transport",async(req,res)=>{try{const u=await userFromReq(req);if(!u)return res.status(401).json({error:"Niet ingelogd"});const q=await pool.query("SELECT jobs_done,total_earned,last_job_at FROM transport_stats WHERE user_id=$1",[u.id]);res.json({stats:q.rows[0]||{jobs_done:0,total_earned:0,last_job_at:null}})}catch(e){console.error(e);res.status(500).json({error:"Transport kon niet worden geladen."})}});app.post("/api/transport/job",async(req,res)=>{try{const u=await userFromReq(req);if(!u)return res.status(401).json({error:"Niet ingelogd"});const jobs={packages:{name:"Pakketbezorging",route:"Kortrijk → Waregem",energy:2,reward:[800,1401],xp:15},wood:{name:"Houttransport",route:"Roeselare → Ieper",energy:3,reward:[1800,2801],xp:25},cars:{name:"Autotransport",route:"Brugge → Kortrijk",energy:4,reward:[3500,5001],xp:40},valuable:{name:"Waardevolle vracht",route:"Oostende → Ieper",energy:5,reward:[6000,9001],xp:60}};const job=jobs[String(req.body.job||"")];if(!job)return res.status(400).json({error:"Onbekende transportopdracht."});if(u.energy<job.energy)return res.status(400).json({error:"Niet genoeg energie voor deze rit."});const reward=crypto.randomInt(job.reward[0],job.reward[1]);let xp=u.xp+job.xp,level=u.level;if(xp>=100){level+=Math.floor(xp/100);xp%=100}const q=await pool.query("UPDATE users SET money=money+$1,energy=energy-$2,xp=$3,level=$4,energy_updated_at=CASE WHEN energy=100 THEN NOW() ELSE energy_updated_at END WHERE id=$5 AND energy>=$2 RETURNING username,money,bank,energy,xp,level,car,equipment,hp,hospital_until,is_admin",[reward,job.energy,xp,level,u.id]);if(!q.rows[0])return res.status(400).json({error:"Niet genoeg energie."});await pool.query("INSERT INTO transport_stats(user_id,jobs_done,total_earned,last_job_at) VALUES($1,1,$2,NOW()) ON CONFLICT(user_id) DO UPDATE SET jobs_done=transport_stats.jobs_done+1,total_earned=transport_stats.total_earned+$2,last_job_at=NOW()",[u.id,reward]);res.json({user:publicUser(q.rows[0]),job:job.name,route:job.route,reward,xpEarned:job.xp})}catch(e){console.error(e);res.status(500).json({error:"Transportopdracht mislukt."})}});app.get("/api/inventory",async(req,res)=>{try{const u=await userFromReq(req);if(!u)return res.status(401).json({error:"Niet ingelogd"});const q=await pool.query("SELECT item_type,item_key,name,SUM(quantity)::int AS quantity,MAX(acquired_at) AS acquired_at FROM inventory_items WHERE user_id=$1 GROUP BY item_type,item_key,name ORDER BY MAX(acquired_at) DESC",[u.id]);res.json({items:q.rows})}catch(e){console.error(e);res.status(500).json({error:"Inventaris kon niet worden geladen."})}});app.get("/api/notifications",async(req,res)=>{try{const u=await userFromReq(req);if(!u)return res.status(401).json({error:"Niet ingelogd"});const q=await pool.query("SELECT id,message,created_at,read_at FROM notifications WHERE user_id=$1 ORDER BY created_at DESC LIMIT 50",[u.id]);res.json({notifications:q.rows,unread:q.rows.filter(n=>!n.read_at).length})}catch(e){console.error(e);res.status(500).json({error:"Meldingen konden niet worden geladen."})}});app.post("/api/notifications/read",async(req,res)=>{try{const u=await userFromReq(req);if(!u)return res.status(401).json({error:"Niet ingelogd"});await pool.query("UPDATE notifications SET read_at=NOW() WHERE user_id=$1 AND read_at IS NULL",[u.id]);res.json({ok:true})}catch(e){res.status(500).json({error:"Meldingen bijwerken mislukt."})}});app.get("/api/chat",async(req,res)=>{try{const u=await userFromReq(req);if(!u)return res.status(401).json({error:"Niet ingelogd"});const q=await pool.query("SELECT c.id,u.username,c.message,c.created_at FROM chat_messages c JOIN users u ON u.id=c.user_id ORDER BY c.created_at DESC LIMIT 50");res.json({messages:q.rows.reverse()})}catch(e){console.error(e);res.status(500).json({error:"Chat kon niet worden geladen."})}});app.post("/api/chat",async(req,res)=>{try{const u=await userFromReq(req);if(!u)return res.status(401).json({error:"Niet ingelogd"});let message=String(req.body.message||"").trim();if(!message)return res.status(400).json({error:"Schrijf eerst een bericht."});if(message.length>300)return res.status(400).json({error:"Een chatbericht mag maximaal 300 tekens bevatten."});const badWords=["fuck","fucking","f*ck","shit","bitch","cunt","klootzak","hoer","kut","tering","tyfus","mongool","debiel","slet","lul","eikel","godverdomme","godver","godferdomme","godfer","kanker","kaka"];const normalize=s=>s.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/[@4]/g,"a").replace(/[3]/g,"e").replace(/[1!|]/g,"i").replace(/[0]/g,"o").replace(/[$5]/g,"s").replace(/[7]/g,"t");const words=message.split(/(\s+)/);message=words.map(part=>{const clean=normalize(part).replace(/[^a-z]/g,"");if(!clean)return part;const hit=badWords.some(w=>clean===normalize(w).replace(/[^a-z]/g,"")||clean.includes(normalize(w).replace(/[^a-z]/g,"")));return hit?"*".repeat(part.length):part}).join("");const q=await pool.query("INSERT INTO chat_messages(user_id,message) VALUES($1,$2) RETURNING id,message,created_at",[u.id,message]);res.json({message:{id:q.rows[0].id,username:u.username,message:q.rows[0].message,created_at:q.rows[0].created_at}})}catch(e){console.error(e);res.status(500).json({error:"Bericht versturen mislukt."})}});app.get("/api/phone/contacts",async(req,res)=>{try{const u=await userFromReq(req);if(!u)return res.status(401).json({error:"Niet ingelogd"});const q=await pool.query("SELECT us.id,us.username,pc.created_at FROM phone_contacts pc JOIN users us ON us.id=pc.contact_user_id WHERE pc.user_id=$1 ORDER BY LOWER(us.username)",[u.id]);res.json({contacts:q.rows})}catch(e){res.status(500).json({error:"Contacten laden mislukt."})}});app.get("/api/phone/contact-search",async(req,res)=>{try{const u=await userFromReq(req);if(!u)return res.status(401).json({error:"Niet ingelogd"});const term=String(req.query.q||"").trim();if(term.length===1)return res.json({users:[]});const q=term?await pool.query("SELECT id,username FROM users WHERE id<>$1 AND username ILIKE $2 AND NOT EXISTS(SELECT 1 FROM phone_contacts pc WHERE pc.user_id=$1 AND pc.contact_user_id=users.id) ORDER BY LOWER(username) LIMIT 50",[u.id,"%"+term+"%"]):await pool.query("SELECT id,username FROM users WHERE id<>$1 AND NOT EXISTS(SELECT 1 FROM phone_contacts pc WHERE pc.user_id=$1 AND pc.contact_user_id=users.id) ORDER BY LOWER(username) LIMIT 50",[u.id]);res.json({users:q.rows})}catch(e){res.status(500).json({error:"Spelers zoeken mislukt."})}});app.post("/api/phone/contacts/:userId",async(req,res)=>{try{const u=await userFromReq(req);if(!u)return res.status(401).json({error:"Niet ingelogd"});const other=Number(req.params.userId);if(!Number.isInteger(other)||other===u.id)return res.status(400).json({error:"Ongeldig contact."});const ex=await pool.query("SELECT username FROM users WHERE id=$1",[other]);if(!ex.rowCount)return res.status(404).json({error:"Speler niet gevonden."});await pool.query("INSERT INTO phone_contacts(user_id,contact_user_id) VALUES($1,$2) ON CONFLICT DO NOTHING",[u.id,other]);res.json({ok:true,username:ex.rows[0].username})}catch(e){res.status(500).json({error:"Contact toevoegen mislukt."})}});app.get("/api/friends/requests",async(req,res)=>{try{const me=await userFromReq(req);if(!me)return res.status(401).json({error:"Niet ingelogd"});const q=await pool.query("SELECT fr.id,fr.sender_id,u.username,fr.created_at FROM friend_requests fr JOIN users u ON u.id=fr.sender_id WHERE fr.receiver_id=$1 AND fr.status='pending' ORDER BY fr.created_at DESC",[me.id]);res.json({requests:q.rows})}catch(e){res.status(500).json({error:"Vriendenverzoeken laden mislukt."})}});
app.post("/api/friends/request/:userId",async(req,res)=>{try{const me=await userFromReq(req);if(!me)return res.status(401).json({error:"Niet ingelogd"});const other=Number(req.params.userId);if(!Number.isInteger(other)||other===me.id)return res.status(400).json({error:"Ongeldige speler."});const p=(await pool.query("SELECT username FROM users WHERE id=$1",[other])).rows[0];if(!p)return res.status(404).json({error:"Speler niet gevonden."});if((await pool.query("SELECT 1 FROM phone_contacts WHERE user_id=$1 AND contact_user_id=$2",[me.id,other])).rowCount)return res.status(400).json({error:"Deze speler staat al in je contacten."});if((await pool.query("SELECT 1 FROM friend_requests WHERE sender_id=$1 AND receiver_id=$2 AND status='pending'",[me.id,other])).rowCount)return res.status(400).json({error:"Vriendenverzoek is al verstuurd."});await pool.query("INSERT INTO friend_requests(sender_id,receiver_id,status,created_at,responded_at) VALUES($1,$2,'pending',NOW(),NULL) ON CONFLICT(sender_id,receiver_id) DO UPDATE SET status='pending',created_at=NOW(),responded_at=NULL",[me.id,other]);await pool.query("INSERT INTO notifications(user_id,message) VALUES($1,$2)",[other,"Vriendenverzoek van "+me.username]);res.json({ok:true,username:p.username})}catch(e){res.status(500).json({error:"Vriendenverzoek versturen mislukt."})}});
app.post("/api/friends/respond/:id",async(req,res)=>{try{const me=await userFromReq(req);if(!me)return res.status(401).json({error:"Niet ingelogd"});const id=Number(req.params.id),accept=req.body.action==="accept";const fr=(await pool.query("SELECT * FROM friend_requests WHERE id=$1 AND receiver_id=$2 AND status='pending'",[id,me.id])).rows[0];if(!fr)return res.status(404).json({error:"Verzoek niet gevonden."});await pool.query("UPDATE friend_requests SET status=$1,responded_at=NOW() WHERE id=$2",[accept?"accepted":"declined",id]);if(accept){await pool.query("INSERT INTO phone_contacts(user_id,contact_user_id) VALUES($1,$2),($2,$1) ON CONFLICT DO NOTHING",[me.id,fr.sender_id]);await pool.query("INSERT INTO notifications(user_id,message) VALUES($1,$2)",[fr.sender_id,me.username+" heeft je vriendenverzoek geaccepteerd."])}res.json({ok:true,accepted:accept})}catch(e){res.status(500).json({error:"Verzoek verwerken mislukt."})}});
app.get("/api/private-chat/users",async(req,res)=>{try{const u=await userFromReq(req);if(!u)return res.status(401).json({error:"Niet ingelogd"});const q=await pool.query("SELECT id,username FROM users WHERE id<>$1 ORDER BY LOWER(username)",[u.id]);res.json({users:q.rows})}catch(e){res.status(500).json({error:"Spelers laden mislukt."})}});app.get("/api/private-chat/:userId",async(req,res)=>{try{const u=await userFromReq(req);if(!u)return res.status(401).json({error:"Niet ingelogd"});const other=Number(req.params.userId);if(!Number.isInteger(other))return res.status(400).json({error:"Ongeldige speler."});const p=await pool.query("SELECT username FROM users WHERE id=$1",[other]);if(!p.rows[0])return res.status(404).json({error:"Speler niet gevonden."});await pool.query("UPDATE private_messages SET read_at=NOW() WHERE receiver_id=$1 AND sender_id=$2 AND read_at IS NULL",[u.id,other]);const q=await pool.query("SELECT p.id,p.sender_id,p.receiver_id,p.message,p.created_at,s.username sender_name FROM private_messages p JOIN users s ON s.id=p.sender_id WHERE (p.sender_id=$1 AND p.receiver_id=$2) OR (p.sender_id=$2 AND p.receiver_id=$1) ORDER BY p.created_at DESC LIMIT 100",[u.id,other]);res.json({username:p.rows[0].username,messages:q.rows.reverse()})}catch(e){res.status(500).json({error:"Privéchat laden mislukt."})}});app.post("/api/private-chat/:userId",async(req,res)=>{try{const u=await userFromReq(req);if(!u)return res.status(401).json({error:"Niet ingelogd"});const other=Number(req.params.userId),message=String(req.body.message||"").trim();if(!message)return res.status(400).json({error:"Schrijf eerst een bericht."});if(message.length>500)return res.status(400).json({error:"Maximaal 500 tekens."});if(other===u.id)return res.status(400).json({error:"Je kunt jezelf geen bericht sturen."});const ex=await pool.query("SELECT 1 FROM users WHERE id=$1",[other]);if(!ex.rowCount)return res.status(404).json({error:"Speler niet gevonden."});await pool.query("INSERT INTO private_messages(sender_id,receiver_id,message) VALUES($1,$2,$3)",[u.id,other,message]);res.json({ok:true})}catch(e){res.status(500).json({error:"Bericht versturen mislukt."})}});app.get("/api/private-chat-unread",async(req,res)=>{try{const u=await userFromReq(req);if(!u)return res.status(401).json({error:"Niet ingelogd"});const q=await pool.query("SELECT COUNT(*)::int count FROM private_messages WHERE receiver_id=$1 AND read_at IS NULL",[u.id]);const latest=await pool.query("SELECT p.id,p.sender_id,p.message,p.created_at,s.username sender_name FROM private_messages p JOIN users s ON s.id=p.sender_id WHERE p.receiver_id=$1 AND p.read_at IS NULL ORDER BY p.created_at DESC LIMIT 1",[u.id]);res.json({count:q.rows[0].count,latest:latest.rows[0]||null})}catch(e){res.status(500).json({error:"Meldingen laden mislukt."})}});app.post("/api/my-city/collect",async(req,res)=>{const rates={hq:80,garage:120,weapons:180,nightclub:260,casino:500,villa:650};try{const u=await userFromReq(req);if(!u)return res.status(401).json({error:"Niet ingelogd"});const q=await pool.query("SELECT building_key,building_level,COALESCE(city_income_at,built_at,NOW()) income_at FROM city_buildings WHERE user_id=$1",[u.id]);if(!q.rowCount)return res.status(400).json({error:"Bouw eerst een gebouw."});const now=Date.now();let total=0;for(const b of q.rows){const hours=Math.min(24,Math.max(0,(now-new Date(b.income_at).getTime())/3600000));total+=Math.floor((rates[b.building_key]||50)*Number(b.building_level)*hours)}if(total<1)return res.status(400).json({error:"Er is nog geen stadsinkomen klaar."});const c=await pool.connect();try{await c.query("BEGIN");await c.query("UPDATE users SET money=money+$1 WHERE id=$2",[total,u.id]);await c.query("UPDATE city_buildings SET city_income_at=NOW() WHERE user_id=$1",[u.id]);await c.query("COMMIT")}finally{c.release()}const nu=await userFromReq(req);res.json({ok:true,amount:total,user:publicUser(nu)})}catch(e){console.error(e);res.status(500).json({error:"Stadsinkomen innen mislukt."})}});app.post("/api/hq/operation",async(req,res)=>{const ops={collection:{name:"Beschermingsgeld",reward:700,xp:25,energy:4,minLevel:1,chance:72,jailChance:5,jailMinutes:2},smuggle:{name:"Smokkelroute",reward:1800,xp:55,energy:7,minLevel:5,chance:52,jailChance:10,jailMinutes:4},heist:{name:"Grote Overval",reward:4500,xp:110,energy:12,minLevel:10,chance:30,jailChance:18,jailMinutes:8}};try{let u=await userFromReq(req);if(!u)return res.status(401).json({error:"Niet ingelogd"});const op=ops[String(req.body.operation||"")];if(!op)return res.status(400).json({error:"Onbekende operatie"});if(u.jailed_until&&new Date(u.jailed_until)>new Date())return res.status(400).json({error:"Je zit in de gevangenis."});if(Number(u.level)<op.minLevel)return res.status(400).json({error:"Je hebt level "+op.minLevel+" nodig."});if(Number(u.energy)<op.energy)return res.status(400).json({error:"Niet genoeg energie."});const success=Math.random()*100<op.chance;if(success){await pool.query("UPDATE users SET money=money+$1,energy=GREATEST(0,energy-$2),xp=xp+$3,level=GREATEST(level,FLOOR((xp+$3)/100)+1) WHERE id=$4",[op.reward,op.energy,op.xp,u.id]);u=await userFromReq(req);return res.json({success:true,name:op.name,reward:op.reward,xpEarned:op.xp,user:publicUser(u)})}const failXp=Math.max(2,Math.floor(op.xp/6)),arrested=Math.random()*100<op.jailChance;if(arrested)await pool.query("UPDATE users SET energy=GREATEST(0,energy-$1),xp=xp+$2,jailed_until=NOW()+($3::text||' minutes')::interval WHERE id=$4",[op.energy,failXp,op.jailMinutes,u.id]);else await pool.query("UPDATE users SET energy=GREATEST(0,energy-$1),xp=xp+$2 WHERE id=$3",[op.energy,failXp,u.id]);u=await userFromReq(req);res.json({success:false,name:op.name,arrested,jailMinutes:arrested?op.jailMinutes:0,xpEarned:failXp,user:publicUser(u)})}catch(e){console.error(e);res.status(500).json({error:"Operatie uitvoeren mislukt."})}});app.get("/api/world/players",async(req,res)=>{try{const u=await userFromReq(req);if(!u)return res.status(401).json({error:"Niet ingelogd"});const q=await pool.query("SELECT w.user_id,u.username,u.avatar,u.level,w.pos_x,w.pos_y,TRUE AS online FROM world_players w JOIN users u ON u.id=w.user_id WHERE w.last_seen>NOW()-INTERVAL '20 seconds' ORDER BY u.username");res.json({players:q.rows,selfId:u.id})}catch(e){res.status(500).json({error:"Spelers laden mislukt."})}});app.post("/api/world/position",async(req,res)=>{try{const u=await userFromReq(req);if(!u)return res.status(401).json({error:"Niet ingelogd"});const x=Math.max(4,Math.min(94,Number(req.body.x)||50)),y=Math.max(7,Math.min(91,Number(req.body.y)||52));await pool.query("INSERT INTO world_players(user_id,pos_x,pos_y,last_seen) VALUES($1,$2,$3,NOW()) ON CONFLICT(user_id) DO UPDATE SET pos_x=EXCLUDED.pos_x,pos_y=EXCLUDED.pos_y,last_seen=NOW()",[u.id,x,y]);res.json({ok:true})}catch(e){res.status(500).json({error:"Positie opslaan mislukt."})}});app.get("/api/my-city",async(req,res)=>{try{const u=await userFromReq(req);if(!u)return res.status(401).json({error:"Niet ingelogd"});const q=await pool.query("SELECT building_key,name,building_level,built_at,pos_x,pos_y,plot_index FROM city_buildings WHERE user_id=$1 ORDER BY id",[u.id]);const power=q.rows.reduce((n,b)=>n+Number(b.building_level)*100,0);const cityLevel=Math.max(1,Math.floor(power/500)+1);res.json({buildings:q.rows,power,cityLevel})}catch(e){res.status(500).json({error:"Stad laden mislukt."})}});app.post("/api/my-city/build",async(req,res)=>{const defs={hq:{name:"Maffia HQ",price:5000},garage:{name:"Garage",price:10000},weapons:{name:"Wapenhandel",price:15000},nightclub:{name:"Nachtclub",price:25000},casino:{name:"Casino",price:50000},villa:{name:"Villa",price:75000}};try{const u=await userFromReq(req);if(!u)return res.status(401).json({error:"Niet ingelogd"});const key=String(req.body.key||""),d=defs[key],plot=Number(req.body.plot);const plots=[[45,61],[61,70],[58,84],[40,91]];if(!d)return res.status(400).json({error:"Onbekend gebouw."});if(!Number.isInteger(plot)||plot<0||plot>=plots.length)return res.status(400).json({error:"Kies eerst een bouwperceel."});const c=await pool.connect();try{await c.query("BEGIN");const ex=await c.query("SELECT 1 FROM city_buildings WHERE user_id=$1 AND building_key=$2",[u.id,key]);if(ex.rowCount){await c.query("ROLLBACK");return res.status(400).json({error:"Dit gebouw staat al in je stad."})}const occupied=await c.query("SELECT 1 FROM city_buildings WHERE user_id=$1 AND plot_index=$2",[u.id,plot]);if(occupied.rowCount){await c.query("ROLLBACK");return res.status(400).json({error:"Dit bouwperceel is al bezet."})}const pay=await c.query("UPDATE users SET money=money-$1 WHERE id=$2 AND money>=$1",[d.price,u.id]);if(!pay.rowCount){await c.query("ROLLBACK");return res.status(400).json({error:"Niet genoeg cash."})}await c.query("INSERT INTO city_buildings(user_id,building_key,name,pos_x,pos_y,plot_index) VALUES($1,$2,$3,$4,$5,$6)",[u.id,key,d.name,plots[plot][0],plots[plot][1],plot]);await c.query("COMMIT")}finally{c.release()}const nu=await userFromReq(req);res.json({user:publicUser(nu),name:d.name})}catch(e){res.status(500).json({error:"Bouwen mislukt."})}});app.post("/api/my-city/upgrade",async(req,res)=>{try{const u=await userFromReq(req);if(!u)return res.status(401).json({error:"Niet ingelogd"});const key=String(req.body.key||"");const q=await pool.query("SELECT * FROM city_buildings WHERE user_id=$1 AND building_key=$2",[u.id,key]);if(!q.rows[0])return res.status(404).json({error:"Gebouw niet gevonden."});const lv=Number(q.rows[0].building_level);if(lv>=10)return res.status(400).json({error:"Dit gebouw is maximaal level 10."});const bases={hq:5000,garage:10000,weapons:15000,nightclub:25000,casino:50000,villa:75000};const cost=Math.round((bases[key]||10000)*(1+lv*.6));const c=await pool.connect();try{await c.query("BEGIN");const pay=await c.query("UPDATE users SET money=money-$1 WHERE id=$2 AND money>=$1",[cost,u.id]);if(!pay.rowCount){await c.query("ROLLBACK");return res.status(400).json({error:"Niet genoeg cash."})}await c.query("UPDATE city_buildings SET building_level=building_level+1 WHERE id=$1",[q.rows[0].id]);await c.query("COMMIT")}finally{c.release()}const nu=await userFromReq(req);res.json({user:publicUser(nu),cost})}catch(e){res.status(500).json({error:"Upgraden mislukt."})}});app.post("/api/my-city/move",async(req,res)=>{try{const u=await userFromReq(req);if(!u)return res.status(401).json({error:"Niet ingelogd"});const key=String(req.body.key||""),x=Math.max(4,Math.min(82,Number(req.body.x)||4)),y=Math.max(5,Math.min(78,Number(req.body.y)||5));const q=await pool.query("UPDATE city_buildings SET pos_x=$1,pos_y=$2 WHERE user_id=$3 AND building_key=$4 RETURNING building_key",[Math.round(x),Math.round(y),u.id,key]);if(!q.rowCount)return res.status(404).json({error:"Gebouw niet gevonden."});res.json({ok:true})}catch(e){res.status(500).json({error:"Plaats opslaan mislukt."})}});app.get("/api/motorclub",async(req,res)=>{try{const u=await userFromReq(req);if(!u)return res.status(401).json({error:"Niet ingelogd"});const q=await pool.query("SELECT c.id,c.name,c.bank,m.role FROM motorcycle_club_members m JOIN motorcycle_clubs c ON c.id=m.club_id WHERE m.user_id=$1",[u.id]);if(!q.rows[0])return res.json({club:null});const x=q.rows[0],members=await pool.query("SELECT u.username,u.level,m.role FROM motorcycle_club_members m JOIN users u ON u.id=m.user_id WHERE m.club_id=$1 ORDER BY m.joined_at",[x.id]);res.json({club:{id:x.id,name:x.name,bank:x.bank,role:x.role,members:members.rows}})}catch(e){res.status(500).json({error:"Motorclub laden mislukt."})}});
app.post("/api/motorclub/create",async(req,res)=>{try{const u=await userFromReq(req);if(!u)return res.status(401).json({error:"Niet ingelogd"});const name=String(req.body.name||"").trim();if(name.length<3||name.length>28)return res.status(400).json({error:"Clubnaam moet 3 tot 28 tekens zijn."});const q=await pool.query("INSERT INTO motorcycle_clubs(name,owner_id) VALUES($1,$2) RETURNING id",[name,u.id]);await pool.query("INSERT INTO motorcycle_club_members(user_id,club_id,role) VALUES($1,$2,'President')",[u.id,q.rows[0].id]);res.json({ok:true})}catch(e){res.status(400).json({error:"Motorclub oprichten mislukt. Mogelijk zit je al in een club of bestaat de naam al."})}});
app.post("/api/motorclub/invite",async(req,res)=>{try{const u=await userFromReq(req);if(!u)return res.status(401).json({error:"Niet ingelogd"});const mine=await pool.query("SELECT club_id,role FROM motorcycle_club_members WHERE user_id=$1",[u.id]);if(!mine.rows[0]||!["President","Vice President"].includes(mine.rows[0].role))return res.status(403).json({error:"Geen toestemming."});const t=await pool.query("SELECT id,username FROM users WHERE username_lower=$1",[String(req.body.username||"").trim().toLowerCase()]);if(!t.rows[0])return res.status(404).json({error:"Speler niet gevonden."});const q=await pool.query("INSERT INTO motorcycle_club_members(user_id,club_id,role) VALUES($1,$2,'Member') ON CONFLICT(user_id) DO NOTHING RETURNING user_id",[t.rows[0].id,mine.rows[0].club_id]);if(!q.rowCount)return res.status(400).json({error:"Speler zit al in een motorclub."});res.json({ok:true,username:t.rows[0].username})}catch(e){res.status(500).json({error:"Lid toevoegen mislukt."})}});
app.get("/api/motorclub/players",async(req,res)=>{try{const u=await userFromReq(req);if(!u)return res.status(401).json({error:"Niet ingelogd"});const q=await pool.query("SELECT id,username,level FROM users WHERE id<>$1 AND id NOT IN (SELECT user_id FROM motorcycle_club_members) ORDER BY LOWER(username)",[u.id]);res.json({players:q.rows})}catch(e){res.status(500).json({error:"Spelers laden mislukt."})}});
app.get("/api/motorclub/clubs",async(req,res)=>{try{const u=await userFromReq(req);if(!u)return res.status(401).json({error:"Niet ingelogd"});const q=await pool.query("SELECT c.id,c.name,u.username president,COUNT(m.user_id)::int members FROM motorcycle_clubs c JOIN users u ON u.id=c.owner_id LEFT JOIN motorcycle_club_members m ON m.club_id=c.id GROUP BY c.id,u.username ORDER BY LOWER(c.name)");res.json({clubs:q.rows})}catch(e){res.status(500).json({error:"Motorclubs laden mislukt."})}});
app.post("/api/motorclub/join-request",async(req,res)=>{try{const u=await userFromReq(req);if(!u)return res.status(401).json({error:"Niet ingelogd"});const clubId=Number(req.body.clubId);const has=await pool.query("SELECT 1 FROM motorcycle_club_members WHERE user_id=$1",[u.id]);if(has.rowCount)return res.status(400).json({error:"Je zit al in een motorclub."});const club=await pool.query("SELECT id,owner_id,name FROM motorcycle_clubs WHERE id=$1",[clubId]);if(!club.rows[0])return res.status(404).json({error:"Motorclub niet gevonden."});await pool.query("INSERT INTO motorcycle_club_requests(club_id,user_id,status) VALUES($1,$2,'pending') ON CONFLICT(club_id,user_id) DO UPDATE SET status='pending',created_at=NOW()",[clubId,u.id]);await pool.query("INSERT INTO notifications(user_id,message) VALUES($1,$2)",[club.rows[0].owner_id,"🏍️ "+u.username+" wil lid worden van "+club.rows[0].name+"."]);res.json({ok:true})}catch(e){res.status(500).json({error:"Aanvraag versturen mislukt."})}});
app.get("/api/motorclub/requests",async(req,res)=>{try{const u=await userFromReq(req);if(!u)return res.status(401).json({error:"Niet ingelogd"});const m=await pool.query("SELECT club_id,role FROM motorcycle_club_members WHERE user_id=$1",[u.id]);if(!m.rows[0]||!["President","Vice President"].includes(m.rows[0].role))return res.json({requests:[]});const q=await pool.query("SELECT r.id,u.username,u.level FROM motorcycle_club_requests r JOIN users u ON u.id=r.user_id WHERE r.club_id=$1 AND r.status='pending' ORDER BY r.created_at",[m.rows[0].club_id]);res.json({requests:q.rows})}catch(e){res.status(500).json({error:"Aanvragen laden mislukt."})}});
app.post("/api/motorclub/request-action",async(req,res)=>{try{const u=await userFromReq(req);if(!u)return res.status(401).json({error:"Niet ingelogd"});const m=await pool.query("SELECT club_id,role FROM motorcycle_club_members WHERE user_id=$1",[u.id]);if(!m.rows[0]||!["President","Vice President"].includes(m.rows[0].role))return res.status(403).json({error:"Geen toestemming."});const q=await pool.query("SELECT r.id,r.user_id,u.username FROM motorcycle_club_requests r JOIN users u ON u.id=r.user_id WHERE r.id=$1 AND r.club_id=$2 AND r.status='pending'",[Number(req.body.requestId),m.rows[0].club_id]);if(!q.rows[0])return res.status(404).json({error:"Aanvraag niet gevonden."});const accept=req.body.action==="accept";if(accept){const a=await pool.query("INSERT INTO motorcycle_club_members(user_id,club_id,role) VALUES($1,$2,'Member') ON CONFLICT(user_id) DO NOTHING RETURNING user_id",[q.rows[0].user_id,m.rows[0].club_id]);if(!a.rowCount)return res.status(400).json({error:"Speler zit al in een Motorclub."})}await pool.query("UPDATE motorcycle_club_requests SET status=$1 WHERE id=$2",[accept?"accepted":"rejected",q.rows[0].id]);await pool.query("INSERT INTO notifications(user_id,message) VALUES($1,$2)",[q.rows[0].user_id,accept?"🏍️ Je Motorclub-aanvraag is goedgekeurd!":"🏍️ Je Motorclub-aanvraag is geweigerd."]);res.json({ok:true,username:q.rows[0].username,action:accept?"accept":"reject"})}catch(e){res.status(500).json({error:"Aanvraag verwerken mislukt."})}});
app.post("/api/motorclub/kick",async(req,res)=>{try{const u=await userFromReq(req);if(!u)return res.status(401).json({error:"Niet ingelogd"});const mine=await pool.query("SELECT club_id,role FROM motorcycle_club_members WHERE user_id=$1",[u.id]);if(!mine.rows[0]||!["President","Vice President"].includes(mine.rows[0].role))return res.status(403).json({error:"Geen toestemming."});const target=await pool.query("SELECT m.user_id,m.role,u.username FROM motorcycle_club_members m JOIN users u ON u.id=m.user_id WHERE m.club_id=$1 AND LOWER(u.username)=LOWER($2)",[mine.rows[0].club_id,String(req.body.username||"")]);if(!target.rows[0])return res.status(404).json({error:"Lid niet gevonden."});if(target.rows[0].role==="President")return res.status(400).json({error:"De President kan niet uit de Motorclub gezet worden."});if(String(target.rows[0].user_id)===String(u.id))return res.status(400).json({error:"Je kunt jezelf niet via deze knop verwijderen."});if(mine.rows[0].role==="Vice President"&&target.rows[0].role==="Vice President")return res.status(403).json({error:"Een Vice President kan geen andere Vice President verwijderen."});await pool.query("DELETE FROM motorcycle_club_members WHERE user_id=$1 AND club_id=$2",[target.rows[0].user_id,mine.rows[0].club_id]);await pool.query("INSERT INTO notifications(user_id,message) VALUES($1,$2)",[target.rows[0].user_id,"🏍️ Je bent uit je Motorclub gezet."]);res.json({ok:true,username:target.rows[0].username})}catch(e){res.status(500).json({error:"Lid verwijderen mislukt."})}});
app.post("/api/motorclub/rank",async(req,res)=>{try{const u=await userFromReq(req);if(!u)return res.status(401).json({error:"Niet ingelogd"});const mine=await pool.query("SELECT club_id,role FROM motorcycle_club_members WHERE user_id=$1",[u.id]);if(!mine.rows[0]||mine.rows[0].role!=="President")return res.status(403).json({error:"Alleen de President kan ranks aanpassen."});const role=String(req.body.role||"");const roles=["Vice President","Sergeant-at-Arms","Road Captain","Enforcer","Prospect","Member"];if(!roles.includes(role))return res.status(400).json({error:"Ongeldige rank."});const target=await pool.query("SELECT m.user_id,m.role,u.username FROM motorcycle_club_members m JOIN users u ON u.id=m.user_id WHERE m.club_id=$1 AND LOWER(u.username)=LOWER($2)",[mine.rows[0].club_id,String(req.body.username||"")]);if(!target.rows[0])return res.status(404).json({error:"Lid niet gevonden."});if(target.rows[0].role==="President")return res.status(400).json({error:"De President-rank kan niet gewijzigd worden."});await pool.query("UPDATE motorcycle_club_members SET role=$1 WHERE user_id=$2 AND club_id=$3",[role,target.rows[0].user_id,mine.rows[0].club_id]);await pool.query("INSERT INTO notifications(user_id,message) VALUES($1,$2)",[target.rows[0].user_id,"🏍️ Je nieuwe Motorclub-rank is "+role+"."]);res.json({ok:true,username:target.rows[0].username,role})}catch(e){res.status(500).json({error:"Rank aanpassen mislukt."})}});
