app.post("/api/home/furniture",async(req,res)=>{try{const u=await userFromReq(req);if(!u)return res.status(401).json({error:"Niet ingelogd."});const catalog={sofa:["sofa","Zetel",500],table:["table","Tafel",250],plant:["plant","Plant",100],dj:["dj","DJ-set",1500],bed:["bed","Bed",700],lamp:["lamp","Lamp",150]};const x=catalog[String(req.body.item||"")];if(!x)return res.status(400).json({error:"Onbekend meubel."});const px=Math.max(5,Math.min(92,Number(req.body.x)||50)),py=Math.max(8,Math.min(88,Number(req.body.y)||50));const q=await pool.query("UPDATE users SET money=money-$1 WHERE id=$2 AND money>=$1 RETURNING money",[x[2],u.id]);if(!q.rows[0])return res.status(400).json({error:"Niet genoeg cash."});const f=await pool.query("INSERT INTO home_furniture(user_id,item_key,name,pos_x,pos_y) VALUES($1,$2,$3,$4,$5) RETURNING *",[u.id,x[0],x[1],px,py]);res.json({ok:true,money:q.rows[0].money,furniture:f.rows[0]})}catch(e){res.status(500).json({error:"Meubel plaatsen mislukt."})}});
