app.get("/api/motorclub/territories",async(req,res)=>{try{const u=await userFromReq(req);if(!u)return res.status(401).json({error:"Niet ingelogd"});const mine=await pool.query("SELECT club_id,role FROM motorcycle_club_members WHERE user_id=$1",[u.id]);const q=await pool.query("SELECT t.id,t.territory_key,t.name,t.income,t.club_id,c.name club_name FROM motorcycle_club_territories t LEFT JOIN motorcycle_clubs c ON c.id=t.club_id ORDER BY t.id");res.json({clubId:mine.rows[0]?.club_id||null,role:mine.rows[0]?.role||null,territories:q.rows})}catch(e){console.error(e);res.status(500).json({error:"Territoria laden mislukt."})}});
app.post("/api/motorclub/territory/attack",async(req,res)=>{const c=await pool.connect();try{const u=await userFromReq(req);if(!u)return res.status(401).json({error:"Niet ingelogd"});const mine=await c.query("SELECT club_id,role FROM motorcycle_club_members WHERE user_id=$1",[u.id]);const m=mine.rows[0];if(!m)return res.status(400).json({error:"Je zit niet in een motorclub."});if(!["President","Vice President","Sergeant-at-Arms","Enforcer"].includes(m.role))return res.status(403).json({error:"Jouw rank mag geen territorium aanvallen."});const tid=Number(req.body.territoryId);await c.query("BEGIN");const tq=await c.query("SELECT * FROM motorcycle_club_territories WHERE id=$1 FOR UPDATE",[tid]);const t=tq.rows[0];if(!t){await c.query("ROLLBACK");return res.status(404).json({error:"Territorium niet gevonden."})}if(String(t.club_id||"")===String(m.club_id)){await c.query("ROLLBACK");return res.status(400).json({error:"Dit territorium is al van jouw club."})}const recent=await c.query("SELECT 1 FROM motorcycle_club_wars WHERE attacker_club_id=$1 AND territory_id=$2 AND created_at>NOW()-INTERVAL '30 minutes'",[m.club_id,tid]);if(recent.rowCount){await c.query("ROLLBACK");return res.status(429).json({error:"Je club moet 30 minuten wachten voor een nieuwe aanval op dit gebied."})}const atk=await c.query("SELECT COALESCE(SUM(u.level),0)::int power,COUNT(*)::int members FROM motorcycle_club_members mm JOIN users u ON u.id=mm.user_id WHERE mm.club_id=$1",[m.club_id]);let def={power:0,members:0};if(t.club_id){const dq=await c.query("SELECT COALESCE(SUM(u.level),0)::int power,COUNT(*)::int members FROM motorcycle_club_members mm JOIN users u ON u.id=mm.user_id WHERE mm.club_id=$1",[t.club_id]);def=dq.rows[0]}const attackPower=Number(atk.rows[0].power)+Math.floor(Math.random()*21),defensePower=Number(def.power)+10+Math.floor(Math.random()*21),win=!t.club_id||attackPower>defensePower;await c.query("INSERT INTO motorcycle_club_wars(attacker_club_id,defender_club_id,territory_id,attacker_user_id,result) VALUES($1,$2,$3,$4,$5)",[m.club_id,t.club_id||null,tid,u.id,win?"won":"lost"]);if(win)await c.query("UPDATE motorcycle_club_territories SET club_id=$1,claimed_at=NOW(),last_income_at=NOW() WHERE id=$2",[m.club_id,tid]);await c.query("COMMIT");res.json({ok:true,win,attackPower,defensePower,name:t.name})}catch(e){try{await c.query("ROLLBACK")}catch{}console.error(e);res.status(500).json({error:"Territoriumaanval mislukt."})}finally{c.release()}});
app.post("/api/motorclub/territory/collect",async(req,res)=>{const c=await pool.connect();try{const u=await userFromReq(req);if(!u)return res.status(401).json({error:"Niet ingelogd"});const mine=await c.query("SELECT club_id,role FROM motorcycle_club_members WHERE user_id=$1",[u.id]);const m=mine.rows[0];if(!m||!["President","Vice President"].includes(m.role))return res.status(403).json({error:"Alleen President of Vice President kan territoriuminkomsten innen."});await c.query("BEGIN");const q=await c.query("SELECT COALESCE(SUM(income*GREATEST(1,FLOOR(EXTRACT(EPOCH FROM (NOW()-last_income_at))/3600))::int),0)::bigint amount FROM motorcycle_club_territories WHERE club_id=$1 AND last_income_at<=NOW()-INTERVAL '1 hour'",[m.club_id]);const amount=Number(q.rows[0].amount||0);if(amount<=0){await c.query("ROLLBACK");return res.status(400).json({error:"Nog geen territoriuminkomsten beschikbaar."})}await c.query("UPDATE motorcycle_clubs SET bank=bank+$1 WHERE id=$2",[amount,m.club_id]);await c.query("UPDATE motorcycle_club_territories SET last_income_at=NOW() WHERE club_id=$1 AND last_income_at<=NOW()-INTERVAL '1 hour'",[m.club_id]);await c.query("COMMIT");res.json({ok:true,amount})}catch(e){try{await c.query("ROLLBACK")}catch{}console.error(e);res.status(500).json({error:"Territoriuminkomsten innen mislukt."})}finally{c.release()}});
app.get("/api/motorclub/wars",async(req,res)=>{try{const u=await userFromReq(req);if(!u)return res.status(401).json({error:"Niet ingelogd"});const m=await pool.query("SELECT club_id FROM motorcycle_club_members WHERE user_id=$1",[u.id]);if(!m.rows[0])return res.json({wars:[]});const q=await pool.query("SELECT w.result,w.created_at,t.name territory,a.name attacker,d.name defender FROM motorcycle_club_wars w JOIN motorcycle_club_territories t ON t.id=w.territory_id JOIN motorcycle_clubs a ON a.id=w.attacker_club_id LEFT JOIN motorcycle_clubs d ON d.id=w.defender_club_id WHERE w.attacker_club_id=$1 OR w.defender_club_id=$1 ORDER BY w.created_at DESC LIMIT 12",[m.rows[0].club_id]);res.json({wars:q.rows})}catch(e){res.status(500).json({error:"Clantoorlogen laden mislukt."})}});
app.get("/api/motorclub/v4",async(req,res)=>{try{const u=await userFromReq(req);if(!u)return res.status(401).json({error:"Niet ingelogd"});const m=await pool.query("SELECT c.id,c.name,c.reputation,c.club_level,m.role FROM motorcycle_club_members m JOIN motorcycle_clubs c ON c.id=m.club_id WHERE m.user_id=$1",[u.id]);if(!m.rows[0])return res.json({club:null});const c=m.rows[0],next=c.club_level*1000;const recent=await pool.query("SELECT mm.mission_key,mm.reward,mm.reputation,mm.completed_at,u.username FROM motorcycle_club_missions mm JOIN users u ON u.id=mm.user_id WHERE mm.club_id=$1 ORDER BY mm.completed_at DESC LIMIT 8",[c.id]);const cd=await pool.query("SELECT MAX(completed_at) last FROM motorcycle_club_missions WHERE user_id=$1",[u.id]);res.json({club:{...c,nextLevelRep:next},lastMissionAt:cd.rows[0].last,recent:recent.rows})}catch(e){res.status(500).json({error:"Motorclub V4 laden mislukt."})}});
app.post("/api/motorclub/v4/mission",async(req,res)=>{const c=await pool.connect();try{const u=await userFromReq(req);if(!u)return res.status(401).json({error:"Niet ingelogd"});const missions={run:{name:"Smokkelrit",energy:8,min:2500,max:5000,rep:120},escort:{name:"Konvooi Escort",energy:12,min:4500,max:8000,rep:200},heist:{name:"Club Heist",energy:18,min:8000,max:14000,rep:320}},key=String(req.body.mission||""),x=missions[key];if(!x)return res.status(400).json({error:"Onbekende MC-missie."});const m=await c.query("SELECT club_id FROM motorcycle_club_members WHERE user_id=$1",[u.id]);if(!m.rows[0])return res.status(400).json({error:"Je zit niet in een motorclub."});if(Number(u.energy)<x.energy)return res.status(400).json({error:"Niet genoeg energie."});const cd=await c.query("SELECT completed_at FROM motorcycle_club_missions WHERE user_id=$1 ORDER BY completed_at DESC LIMIT 1",[u.id]);if(cd.rows[0]&&Date.now()-new Date(cd.rows[0].completed_at).getTime()<300000)return res.status(429).json({error:"Wacht 5 minuten voor je volgende MC-missie."});const reward=Math.floor(x.min+Math.random()*(x.max-x.min+1));await c.query("BEGIN");await c.query("UPDATE users SET energy=GREATEST(0,energy-$1),energy_updated_at=NOW() WHERE id=$2",[x.energy,u.id]);await c.query("UPDATE motorcycle_clubs SET bank=bank+$1,reputation=reputation+$2 WHERE id=$3",[reward,x.rep,m.rows[0].club_id]);await c.query("INSERT INTO motorcycle_club_missions(club_id,user_id,mission_key,reward,reputation) VALUES($1,$2,$3,$4,$5)",[m.rows[0].club_id,u.id,key,reward,x.rep]);const cq=await c.query("SELECT reputation,club_level FROM motorcycle_clubs WHERE id=$1 FOR UPDATE",[m.rows[0].club_id]);let lv=Number(cq.rows[0].club_level),rep=Number(cq.rows[0].reputation);while(rep>=lv*1000&&lv<50)lv++;await c.query("UPDATE motorcycle_clubs SET club_level=$1 WHERE id=$2",[lv,m.rows[0].club_id]);await c.query("COMMIT");res.json({ok:true,name:x.name,reward,reputation:x.rep,clubLevel:lv,user:publicUser(await userFromReq(req))})}catch(e){try{await c.query("ROLLBACK")}catch{}console.error(e);res.status(500).json({error:"MC-missie mislukt."})}finally{c.release()}});
