app.post("/api/house/furniture",async(req,res)=>{try{const u=await userFromReq(req);if(!u)return res.status(401).json({error:"Niet ingelogd."});const catalog={sofa:["Zetel",500],table:["Tafel",250],plant:["Plant",100],tv:["TV",900],dj:["DJ-set",1500],bed:["Bed",700],lamp:["Lamp",150],rug:["Tapijt",300],cabinet:["Kast",450]};const key=String(req.body.item||""),x=catalog[key];if(!x)return res.status(400).json({error:"Onbekend meubel."});const px=Math.max(6,Math.min(94,Number(req.body.x)||50)),py=Math.max(10,Math.min(90,Number(req.body.y)||55));const q=await pool.query("UPDATE users SET money=money-$1 WHERE id=$2 AND money>=$1 RETURNING money",[x[1],u.id]);if(!q.rows[0])return res.status(400).json({error:"Niet genoeg cash."});const f=await pool.query("INSERT INTO home_furniture(user_id,item_key,name,pos_x,pos_y,rotation) VALUES($1,$2,$3,$4,$5,0) RETURNING *",[u.id,key,x[0],px,py]);res.json({ok:true,money:q.rows[0].money,furniture:f.rows[0]})}catch(e){res.status(500).json({error:"Meubel kopen mislukt."})}});
