app.get("/api/house-v4/:username",async(req,res)=>{try{const me=await userFromReq(req);if(!me)return res.status(401).json({error:"Niet ingelogd."});const oq=await pool.query("SELECT id,username,money FROM users WHERE LOWER(username)=LOWER($1)",[String(req.params.username||"")]);const owner=oq.rows[0];if(!owner)return res.status(404).json({error:"Woning niet gevonden."});await pool.query("INSERT INTO houses(user_id) VALUES($1) ON CONFLICT(user_id) DO NOTHING",[owner.id]);const h=(await pool.query("SELECT house_level,style,privacy FROM houses WHERE user_id=$1",[owner.id])).rows[0]||{};if(owner.id!==me.id&&h.privacy&&h.privacy!=="public")return res.status(403).json({error:"Deze woning is privé."});const fq=await pool.query("SELECT id,item_key,name,pos_x,pos_y,rotation,room_index FROM home_furniture WHERE user_id=$1 ORDER BY room_index,id",[owner.id]);const prices={sofa:500,table:250,plant:100,tv:900,dj:1500,bed:700,lamp:150,rug:300,cabinet:450};const furnitureValue=fq.rows.reduce((n,x)=>n+(prices[x.item_key]||100),0);const level=Number(h.house_level||1);const houseValue=[0,15000,40000,100000,250000,600000][level]||600000;res.json({owner:owner.username,isOwner:String(owner.id)===String(me.id),level,style:h.style||"basic",privacy:h.privacy||"public",rooms:Math.min(5,Math.max(1,level)),furniture:fq.rows,value:houseValue+furnitureValue,prestige:level*100+Math.floor(furnitureValue/100)})}catch(e){console.error(e);res.status(500).json({error:"Woning V4 laden mislukt."})}});
app.patch("/api/house-v4/furniture/:id",async(req,res)=>{try{const me=await userFromReq(req);if(!me)return res.status(401).json({error:"Niet ingelogd."});const h=(await pool.query("SELECT COALESCE(house_level,1) house_level FROM houses WHERE user_id=$1",[me.id])).rows[0]||{house_level:1};const room=Math.max(0,Math.min(Number(h.house_level)-1,Number(req.body.room)||0));const x=Math.max(5,Math.min(95,Number(req.body.x)||50)),y=Math.max(12,Math.min(90,Number(req.body.y)||55)),rot=((Number(req.body.rotation)||0)%4+4)%4;const q=await pool.query("UPDATE home_furniture SET pos_x=$1,pos_y=$2,rotation=$3,room_index=$4 WHERE id=$5 AND user_id=$6 RETURNING *",[x,y,rot,room,req.params.id,me.id]);if(!q.rows[0])return res.status(404).json({error:"Meubel niet gevonden."});res.json({ok:true,furniture:q.rows[0]})}catch(e){res.status(500).json({error:"Meubel opslaan mislukt."})}});
